const items = $input.all();
const newItem = items[0];

newItem.json = newItem.json || {};

// Find whatever binary key was sent (e.g., 'file', 'file0', 'data')
const binaryKey = Object.keys(newItem.binary || {})[0];

if (binaryKey) {
  const binaryData = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  newItem.json.imagebase64 = binaryData.toString('base64');
  newItem.json.mimeType = newItem.binary[binaryKey].mimeType;
} else {
  newItem.json.imagebase64 = "";
  newItem.json.mimeType = "image/jpeg";
}

return [newItem];

const items = $input.all();

return items.map((item) => {
  try {
    // Get Gemini's response
    const parts =
      item.json.candidates?.[0]?.content?.parts || [];

    const responseText = parts
      .map(part => part.text || "")
      .join("\n");

    if (!responseText) {
      throw new Error("Gemini returned empty text");
    }

    // Extract JSON from Markdown code fences
    const match = responseText.match(
      /```(?:json)?\s*([\s\S]*?)```/i
    );

    let jsonText;

    if (match) {
      jsonText = match[1].trim();
    } else {
      // Fallback: find JSON object in response
      const start = responseText.indexOf("{");
      const end = responseText.lastIndexOf("}");

      if (start === -1 || end === -1) {
        throw new Error("No JSON object found in Gemini response");
      }

      jsonText = responseText.substring(start, end + 1);
    }

    // Parse JSON
    const extracted = JSON.parse(jsonText);

    // Return structured result
    return {
      json: {
        success: true,
        document: extracted
      }
    };

  } catch (error) {
    return {
      json: {
        success: false,
        error: error.message,
        document: null
      }
    };
  }
});
